import test from 'node:test';
import assert from 'node:assert/strict';
import { statement } from '../src/statements.js';
import { createInvoice, issueInvoice, applyVoucher, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('statement returns CUSTOMER_NOT_FOUND for unknown customer', () => {
  const result = statement('C-999', [], '2026-10-31');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement returns empty invoices for customer with no issued invoices', () => {
  const result = statement('C-001', [], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement includes issued invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = statement('C-001', [issued.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, issued.value.number);
});

test('statement includes partially_paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const partial = recordPayment(issued.value, { amount: 20000, date: '2026-10-15' });

  const result = statement('C-001', [partial.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement excludes draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const result = statement('C-001', [r.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement excludes paid invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-15' });

  const result = statement('C-001', [paid.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement excludes invoices after asOf date', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-11-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = statement('C-001', [issued.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement includes invoices with issueDate equal to asOf', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-31',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = statement('C-001', [issued.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement returns invoice details', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(r.value, []);

  const result = statement('C-001', [issued.value], '2026-10-31');
  const inv = result.value.invoices[0];

  assert.equal(inv.number, issued.value.number);
  assert.equal(inv.issueDate, issued.value.issueDate);
  assert.equal(inv.dueDate, issued.value.dueDate);
  assert.equal(typeof inv.total, 'number');
  assert.equal(typeof inv.due, 'number');
});

test('statement calculates due correctly for unpaid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const totals = invoiceTotals(issued.value);

  const result = statement('C-001', [issued.value], '2026-10-31');
  const inv = result.value.invoices[0];

  assert.equal(inv.due, totals.total);
});

test('statement calculates due correctly for partially paid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const partial = recordPayment(issued.value, { amount: 20000, date: '2026-10-15' });
  const totals = invoiceTotals(partial.value);

  const result = statement('C-001', [partial.value], '2026-10-31');
  const inv = result.value.invoices[0];

  assert.equal(inv.due, totals.total - 20000);
});

test('statement sorts invoices by issueDate ascending', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-20',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const issued3 = issueInvoice(r3.value, ['INV-2026-0001', 'INV-2026-0002']);

  const result = statement('C-001', [issued1.value, issued2.value, issued3.value], '2026-10-31');
  const issueDates = result.value.invoices.map((inv) => inv.issueDate);

  assert.deepEqual(issueDates, ['2026-10-07', '2026-10-15', '2026-10-20']);
});

test('statement calculates totalDue as sum of due amounts', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });

  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);

  const result = statement('C-001', [issued1.value, issued2.value], '2026-10-31');
  const expectedTotalDue = result.value.invoices.reduce((sum, inv) => sum + inv.due, 0);

  assert.equal(result.value.totalDue, expectedTotalDue);
});

test('statement with partially paid invoice includes correct due', () => {
